package com.company.platform.order;
import com.company.platform.order.domain.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class TenantIsolationTest{@Test void repositoryPortRequiresTenantScopedLookup(){UUID a=UUID.randomUUID(),b=UUID.randomUUID(),id=UUID.randomUUID();Map<String,Order> data=new HashMap<>();var o=Order.rehydrate(id,a,new OrderNumber("ORD-A"),UUID.randomUUID(),UUID.randomUUID(),OrderStatus.CONFIRMED,Currency.getInstance("USD"),Money.zero(Currency.getInstance("USD")),null,null,List.of());data.put(a+":"+id,o);OrderRepository r=new OrderRepository(){public Order save(Order x){return x;}public Optional<Order> findByTenantIdAndId(UUID t,UUID x){return Optional.ofNullable(data.get(t+":"+x));}public Optional<Order> findByTenantIdAndOrderNumber(UUID t,String n){return Optional.empty();}public List<Order> findByTenantIdAndCustomerId(UUID t,UUID c){return List.of();}public List<Order> findByTenantIdAndStoreId(UUID t,UUID s){return List.of();}};assertTrue(r.findByTenantIdAndId(a,id).isPresent());assertTrue(r.findByTenantIdAndId(b,id).isEmpty());}}
